import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.sV-XtlWr.js";const p=JSON.parse('{"title":"License","description":"What the FSL-1.1-MIT license lets you do with Piwi, what it rules out, which parts are MIT, and when each release becomes MIT.","frontmatter":{"title":"License","description":"What the FSL-1.1-MIT license lets you do with Piwi, what it rules out, which parts are MIT, and when each release becomes MIT.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/license.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/license.html"}],["meta",{"property":"og:title","content":"License | Piwi Dashboard"}],["meta",{"property":"og:description","content":"What the FSL-1.1-MIT license lets you do with Piwi, what it rules out, which parts are MIT, and when each release becomes MIT."}]]},"headers":[],"relativePath":"guide/license.md","filePath":"guide/license.md","lastUpdated":1790783991000}'),o={name:"guide/license.md"};function s(n,e,h,l,c,d){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h1><p>Piwi is fair source. The dashboard, the server, the desktop app and the browser extension are published under the <a href="https://github.com/PiwiTests/platform/blob/main/LICENSE" target="_blank" rel="noreferrer">Functional Source License, Version 1.1, MIT Future License</a> (FSL-1.1-MIT). The parts that run inside your own projects are MIT.</p><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><p>Use Piwi for free, for any purpose other than competing with it. That covers:</p><ul><li>running it for your team or your whole company, on your own servers, in the desktop app or from the Docker image;</li><li>changing the code, and running your changed copy;</li><li>using it for teaching and non-commercial research;</li><li>setting it up or running it for a client who uses it for their own work, as a consultant or contractor.</li></ul><h2 id="what-it-rules-out" tabindex="-1">What it rules out <a class="header-anchor" href="#what-it-rules-out" aria-label="Permalink to &quot;What it rules out&quot;">​</a></h2><p>Making Piwi available to others in a commercial product or service that substitutes for it, or that offers the same or substantially similar functionality. Selling hosted Piwi is a competing use, and so is reselling it, or a product built from its code, under another name.</p><p>If you redistribute Piwi or a modified copy, include the license, or a link to it, and keep the copyright notices. The license gives no right to use the Piwi name or logo beyond saying where the software comes from.</p><h2 id="each-release-becomes-mit-after-two-years" tabindex="-1">Each release becomes MIT after two years <a class="header-anchor" href="#each-release-becomes-mit-after-two-years" aria-label="Permalink to &quot;Each release becomes MIT after two years&quot;">​</a></h2><p>Every release carries an irrevocable grant: two years after the date it is published, that release is also available under the MIT License, with no restriction on competing use. Newer releases stay under FSL-1.1-MIT until their own two years are up.</p><h2 id="which-parts-are-mit" tabindex="-1">Which parts are MIT <a class="header-anchor" href="#which-parts-are-mit" aria-label="Permalink to &quot;Which parts are MIT&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>License</th></tr></thead><tbody><tr><td>Dashboard, server (<code>@piwitests/server</code> and the Docker image), desktop app, browser extension</td><td>FSL-1.1-MIT</td></tr><tr><td>Playwright reporter (<code>@piwitests/reporter</code>)</td><td>MIT</td></tr><tr><td>Backend-log integrations (Nitro, ASP.NET Core, Serilog)</td><td>MIT</td></tr><tr><td>Examples</td><td>MIT</td></tr></tbody></table><p>The reporter and the integrations run inside your test suite and your application, so they keep the most permissive license: nothing you ship depends on FSL-1.1-MIT code.</p><p>Releases up to v0.39.x were published under the MIT License, and stay under it.</p><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><p>Not sure whether what you have in mind is a competing use? Ask in <a href="https://github.com/PiwiTests/platform/discussions" target="_blank" rel="noreferrer">GitHub Discussions</a> before you build it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./privacy.html">Privacy &amp; data flow</a> — what leaves your server, and what never does</li><li><a href="./comparison.html">Why Piwi?</a> — how Piwi compares with the tools you may already use</li></ul>',18)])])}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
